const GR_P13B=[
 ["Cannot help doing with ないではいられない","Verb ない-form + ではいられない","ないではいられない (nai de wa irarenai) after the ない-form of a verb means that a feeling is so strong that you cannot stop yourself from doing the action: “cannot help doing”. 笑わないではいられません means “I cannot help laughing”. For する, use しないではいられません. The polite form is ではいられません.",[["笑わないでは","warawanaideha","laugh (ない-form + では)"],["いられません","iraremasen","cannot stay"],["。","",""]],"I cannot help laughing."],
 ["Cannot do it with わけにはいきません","Dictionary form + わけにはいきません","わけにはいきません (wake ni wa ikimasen) after the dictionary form of a verb means that you cannot do the action because of a reason, a duty or a rule, even if you want to: “cannot do it”. 休むわけにはいきません means “I cannot take a rest”. With the ない-form, the meaning is the opposite: 行かないわけにはいきません means “I must go”.",[["明日","ashita","tomorrow"],["は","wa","(topic)"],["休む","yasumu","to rest"],["わけにはいきません","wakenihaikimasen","cannot"],["。","",""]],"I cannot take a rest tomorrow."],
 ["Instead of with かわりに","Noun の or dictionary form + かわりに","かわりに (kawari ni) means “instead of”. After a noun, add の: 肉のかわりに means “instead of meat”. After a verb, use the dictionary form: 電話するかわりに means “instead of calling”. The words after かわりに say what you do in its place.",[["肉","niku","meat"],["の","no","’s"],["かわりに","kawarini","instead of"],["魚","sakana","fish"],["を","o","(object)"],["食べます","tabemasu","eat"],["。","",""]],"I eat fish instead of meat."],
 ["There is no way to with ようがありません","Verb stem + ようがありません","ようがありません (you ga arimasen) after a verb stem means that there is no way or no method to do the action: “cannot possibly”. 答えようがありません means “there is no way to answer”. For する, use しようがありません. For 来る, use きようがありません.",[["質問","shitsumon","question"],["が","ga","(subject)"],["難しくて","muzukashikute","difficult (て-form)"],["、","",""],["答え","kotae","answer (stem)"],["ようがありません","yougaarimasen","there is no way to"],["。","",""]],"The question is so difficult that there is no way to answer."],
 ["Unless with ないと","Verb ない-form + と、negative result","The ない-form of a verb plus と (to) says: if you do not do this, a bad result follows. The second part is usually a negative or unpleasant result. 寝ないと眠いです means “if you do not sleep, you will be sleepy”. In casual speech, ないと alone can also mean “I must”.",[["早く","hayaku","early"],["寝ない","nenai","do not sleep"],["と","to","and"],["、","",""],["明日","ashita","tomorrow"],["は","wa","(topic)"],["眠い","nemui","sleepy"],["です","desu","is"],["。","",""]],"If you do not sleep early, you will be sleepy tomorrow."]
];
